def monitor_flag_rate(events):
    """The share of transcripts whose flagged value is True (SPEC.md section 1)."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event.get("flagged") is True)
    return hits / len(events)


def pooled_flag_rate(groups):
    """The transcript-weighted flag rate across groups (SPEC.md section 2)."""
    events = [event for group_events in groups.values() for event in group_events]
    return monitor_flag_rate(events)


def flags_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (SPEC.md section 3)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def flag_rate_by_group(groups):
    """Map each group name to its flag rate, in name order (SPEC.md section 9)."""
    return {
        name: monitor_flag_rate(groups[name]) if groups[name] else None
        for name in sorted(groups)
    }


def longest_flag_streak(daily_counts):
    """Return the longest run of entries greater than zero (SPEC.md section 10)."""
    best = current = 0
    for count in daily_counts:
        if count > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best
