{"file_path":"safety_evals/report.py","content":""""AI alignment evaluation: monitor flag statistics over model transcripts."""

from safety_evals.loader import daily_flag_counts
from safety_evals.metrics import flags_in_window, monitor_flag_rate, pooled_flag_rate


def monitor_summary(groups, days):
    """Summarize pooled rate, recent flags, and nonempty groups (SPEC.md section 7)."""
    all_events = [event for group_events in groups.values() for event in group_events]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        daily_counts = daily_flag_counts(all_events, first_day, last_day)
        recent = flags_in_window(daily_counts, days)
    else:
        recent = 0

    nonempty_groups = sum(bool(group_events) for group_events in groups.values())
    return {
        "rate": round(pooled_flag_rate(groups), 3),
        "recent": recent,
        "groups": nonempty_groups,
    }


def top_flagged_groups(groups, n):
    """Return nonempty groups by descending rate, breaking ties by name (SPEC.md section 8)."""
    ranked = [
        (name, monitor_flag_rate(events))
        for name, events in groups.items()
        if events
    ]
    ranked.sort(key=lambda item: (-item[1], item[0]))
    return [name for name, _ in ranked[:n]]
